Run("transaction ordering",()=>{var source=File.ReadAllText(RepoFile("src","Build.Host","Program.cs"));var inventory=source.IndexOf("Sources.Inventory",StringComparison.Ordinal);var ownership=source.IndexOf("s.Start(sentinel)",StringComparison.Ordinal);var worksheet=source.IndexOf("s.PrepareWorksheet()",ownership,StringComparison.Ordinal);var import=source.IndexOf("s.Import(import)",worksheet,StringComparison.Ordinal);var save=source.IndexOf("s.Save(built)",import,StringComparison.Ordinal);var metadata=source.IndexOf("Metadata.Update",save,StringComparison.Ordinal);var cleanup=source.IndexOf("s.Dispose()",metadata,StringComparison.Ordinal);var publication=source.IndexOf("Publication.Publish",cleanup,StringComparison.Ordinal);Assert(inventory>=0&&inventory<ownership&&ownership<worksheet&&worksheet<import&&import<save&&save<metadata&&metadata<cleanup&&cleanup<publication);});
