void Run(string n,Action a){total++;try{a();}catch(Exception e){fs.Add($"FAIL {n}: {e.GetType().Name}: {e.Message}");}}void Assert(bool x){if(!x)throw new Exception("assertion failed");}void Throws<T>(Action a)where T:Exception{try{a();}catch(T){return;}throw new Exception($"expected {typeof(T).Name}");}string Temp(string s){var p=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".cls");File.WriteAllText(p,s,new UTF8Encoding(false));return p;}Ownership Own(Guid? id=null)=>new(123,new DateTimeOffset(2026,1,1,0,0,0,TimeSpan.Zero),@"C:\Program Files\Microsoft Office\EXCEL.EXE",id??Guid.NewGuid(),@"C:\temp\sentinel.xlsx");
string RepoFile(params string[] parts){const string variable="VMF_TEST_REPOSITORY_ROOT";var suppliedRoot=Environment.GetEnvironmentVariable(variable);string root;if(suppliedRoot is not null){if(!Path.IsPathFullyQualified(suppliedRoot))throw new InvalidOperationException($"Test-harness repository root from {variable} must be an absolute path.");root=Path.GetFullPath(suppliedRoot);if(!File.Exists(Path.Combine(root,".vmf-root")))throw new DirectoryNotFoundException($"Test-harness repository root from {variable} does not contain .vmf-root: {root}");}else{var directory=new DirectoryInfo(AppContext.BaseDirectory);while(directory is not null&&!File.Exists(Path.Combine(directory.FullName,".vmf-root")))directory=directory.Parent;root=directory?.FullName??throw new DirectoryNotFoundException("Repository root not found.");}return Path.Combine(root,Path.Combine(parts));}
sealed class Tree:IDisposable{public string Path{get;}=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"vmf-host-tests",Guid.NewGuid().ToString("N"));public Tree()=>Directory.CreateDirectory(Path);public void Dispose(){if(Directory.Exists(Path))Directory.Delete(Path,true);}}
